insert into questions (exam_type, year, question_no, field_tags, difficulty, body, choices, official_answer, explanation, source) values
('D2', 'gen-batch-002', 31, ARRAY['resilience']::text[], 2, '単一 AZ で稼働している Web サーバー群を、AZ 障害時にもサービス継続できるようにしたい。最も基本的な対策はどれか。', '{"ア":"同一 AZ 内でインスタンス数を 2 倍にする","イ":"複数の AZ にまたがる Auto Scaling グループと、クロスゾーン負荷分散を有効にした ELB を構成する","ウ":"インスタンスのルート EBS ボリュームのスナップショットを毎時取得する","エ":"より大きなインスタンスタイプに変更する"}'::jsonb, 'イ', '高可用性の基本は複数 AZ への分散。ASG を複数サブネット(AZ)に広げ、ELB がヘルスチェックで正常なターゲットのみへ振り分ける。単一 AZ での台数増加やスケールアップは AZ 障害に無力。スナップショットは復旧材料であって可用性そのものではない。', 'generated'),
('D2', 'gen-batch-002', 32, ARRAY['database']::text[], 2, 'RDS の「マルチ AZ 配置」の主な目的として正しいものはどれか。', '{"ア":"読み取りクエリを複数インスタンスへ分散して性能を上げる","イ":"リージョン全体の障害に備えて別リージョンへ複製する","ウ":"プライマリ障害時にスタンバイへ自動フェイルオーバーし、可用性を高める","エ":"ストレージ料金を半額にする"}'::jsonb, 'ウ', 'マルチ AZ は同期レプリケーションされたスタンバイを別 AZ に持ち、プライマリ障害やメンテナンス時に自動フェイルオーバーする HA 機能。読み取り分散はリードレプリカの役割。別リージョン複製はクロスリージョンリードレプリカやグローバル DB。', 'generated'),
('D2', 'gen-batch-002', 33, ARRAY['integration']::text[], 2, 'フロントエンドが受け付けた注文を、バックエンドの処理能力を超えるバーストがあっても取りこぼさず非同期に処理したい。適切なサービスはどれか。', '{"ア":"フロントから RDS へ直接 INSERT し、cron で集計する","イ":"フロントとバックを同期 REST 呼び出しで密結合する","ウ":"Amazon SNS のみでファンアウトする","エ":"Amazon SQS キューを挟み、ワーカーがポーリングして処理する"}'::jsonb, 'エ', 'SQS はバッファとして働き、生産者と消費者を疎結合にする。バーストはキューに滞留し、ワーカーは自分のペースで取り出せる(必要ならキュー長で Auto Scaling)。同期呼び出しはバックエンド過負荷で失敗が伝播する。SNS はプッシュ型で滞留による平準化はしない。', 'generated'),
('D2', 'gen-batch-002', 34, ARRAY['integration']::text[], 3, 'SQS で処理に失敗し続けるメッセージが、正常なメッセージの処理を妨げている。対策として適切なものはどれか。', '{"ア":"デッドレターキュー(DLQ)を設定し、最大受信回数を超えたメッセージを退避する","イ":"可視性タイムアウトを 0 秒にする","ウ":"キューを標準からリアルタイムに変更する","エ":"メッセージ保持期間を 1 分に短縮する"}'::jsonb, 'ア', 'DLQ に maxReceiveCount を設定すると、規定回数リトライしても処理できない「毒メッセージ」を別キューへ隔離でき、正常な処理を止めない。退避分は後から調査・再投入できる。可視性タイムアウト 0 は多重処理を招く。', 'generated'),
('D2', 'gen-batch-002', 35, ARRAY['integration']::text[], 2, '1 件のイベント(画像アップロード)を、サムネイル生成・メタデータ登録・通知メール送信の 3 つの独立処理へ同時に配信したい。適切な構成はどれか。', '{"ア":"1 つの SQS キューを 3 つのワーカーで共有する","イ":"3 処理を 1 つの Lambda に順次実装する","ウ":"SNS トピックに 3 つの SQS キュー/Lambda をサブスクライブするファンアウト構成","エ":"EventBridge スケジュールで 5 分ごとに全処理を実行する"}'::jsonb, 'ウ', 'SNS のファンアウトは 1 メッセージを複数サブスクライバ(SQS、Lambda、HTTPS)へ複製配信でき、各処理を独立にスケール/リトライできる。単一 SQS を共有すると 1 メッセージは 1 コンシューマしか受け取れない。', 'generated'),
('D2', 'gen-batch-002', 36, ARRAY['compute']::text[], 2, 'Auto Scaling グループのヘルスチェックで「ELB ヘルスチェック」を有効にする利点はどれか。', '{"ア":"スポットインスタンスの中断を防げる","イ":"OS は起動しているがアプリが応答しないインスタンスも異常と判定して置き換えられる","ウ":"スケールアウトの速度が 2 倍になる","エ":"リザーブドインスタンスの割引が適用される"}'::jsonb, 'イ', '既定の EC2 ステータスチェックはハイパーバイザ/OS レベルの健全性しか見ない。ELB ヘルスチェックを併用すると、ターゲットグループの HTTP 応答などアプリ層の異常も検知し、ASG が不健全インスタンスを終了・再作成する。', 'generated'),
('D2', 'gen-batch-002', 37, ARRAY['network']::text[], 3, 'プライマリサイト(us-east-1)がダウンした際に、自動的にセカンダリサイト(us-west-2)へトラフィックを切り替えたい。DNS レイヤーでの実現方法はどれか。', '{"ア":"Route 53 のフェイルオーバールーティングポリシーとヘルスチェックを設定する","イ":"Route 53 のシンプルルーティングで 2 つの値を登録する","ウ":"ALB のリスナールールで送信先リージョンを分岐する","エ":"CloudFront のオリジンを手動で切り替える"}'::jsonb, 'ア', 'Route 53 フェイルオーバールーティングは、プライマリレコードにヘルスチェックを関連付け、異常時にセカンダリレコードへ自動で解決先を切り替える。シンプルルーティングはヘルスチェック連動の自動切替をしない。ALB は単一リージョン内のみ。', 'generated'),
('D2', 'gen-batch-002', 38, ARRAY['storage']::text[], 2, 'S3 バケットのオブジェクトを、別リージョンにも自動複製してリージョン障害やコンプライアンスに備えたい。設定すべき機能はどれか。', '{"ア":"S3 Transfer Acceleration","イ":"S3 ライフサイクルルールで別リージョンへ移動する","ウ":"S3 Select","エ":"クロスリージョンレプリケーション(CRR)。前提としてバージョニングを有効化する"}'::jsonb, 'エ', 'CRR はソース/宛先双方でバージョニングを有効にしたうえで、新規オブジェクトを指定リージョンのバケットへ非同期複製する。ライフサイクルはストレージクラス遷移や失効の機能で、リージョン間コピーはできない。Transfer Acceleration は転送高速化。', 'generated'),
('D2', 'gen-batch-002', 39, ARRAY['storage']::text[], 2, 'アプリのバグでユーザーが重要な S3 オブジェクトを上書き・削除してしまう事故に備えたい。最小構成の対策はどれか。', '{"ア":"バケットのバージョニングを有効にし、必要なら MFA Delete も設定する","イ":"オブジェクトごとに手動でローカルへダウンロードしてバックアップする","ウ":"バケットポリシーで DELETE を全面禁止する","エ":"ストレージクラスを Glacier Deep Archive に変更する"}'::jsonb, 'ア', 'バージョニングは上書き/削除しても以前のバージョンを保持し、復元できる。削除は「削除マーカー」が付くだけなので巻き戻せる。MFA Delete でバージョンの完全削除に多要素認証を要求できる。DELETE 全面禁止は正常運用も妨げる。', 'generated'),
('D2', 'gen-batch-002', 40, ARRAY['resilience']::text[], 3, '災害復旧(DR)戦略のうち、「パイロットライト」の説明として正しいものはどれか。', '{"ア":"本番と同等の環境を別リージョンで常時フル稼働させ、即時に切り替える","イ":"コアな要素(データベースのレプリカ等)は常時稼働させ、アプリ層は最小限にして障害時に迅速に起動・拡張する","ウ":"バックアップのみを別リージョンに保管し、障害時に一から構築する","エ":"縮小版の本番環境を常時稼働させ、障害時にスケールアップする"}'::jsonb, 'イ', 'パイロットライトは、DB 複製など「消えると困る中核」だけを常時起動し、コンピュート層はテンプレート化して停止/最小化しておき、発災時に点火(起動・スケール)する。フル稼働はマルチサイト、縮小版常時稼働はウォームスタンバイ、保管のみはバックアップ&リストア。', 'generated'),
('D2', 'gen-batch-002', 41, ARRAY['resilience']::text[], 3, 'RTO(目標復旧時間)を数分、RPO(目標復旧時点)をほぼゼロにしたい。コストは相応にかけられる。適切な DR 戦略はどれか。', '{"ア":"バックアップ&リストア","イ":"パイロットライト","ウ":"マルチサイト アクティブ/アクティブ(またはホットスタンバイ)構成","エ":"スナップショットの週次コピーのみ"}'::jsonb, 'ウ', 'RTO 数分・RPO ほぼゼロを満たすには、別リージョンでも本番同等の環境を常時稼働させ、データを継続同期する必要がある(マルチサイト/ホットスタンバイ)。バックアップ&リストアやパイロットライトは復旧に時間がかかり RTO を満たせない。', 'generated'),
('D2', 'gen-batch-002', 42, ARRAY['database']::text[], 3, 'DynamoDB テーブルを複数リージョンで読み書き可能にし、リージョン障害時にもアプリを継続させたい。適切な機能はどれか。', '{"ア":"DynamoDB Accelerator(DAX)","イ":"オンデマンドバックアップを別リージョンにコピーする","ウ":"グローバルセカンダリインデックス(GSI)を追加する","エ":"DynamoDB グローバルテーブル(マルチリージョン、マルチアクティブ)"}'::jsonb, 'エ', 'グローバルテーブルは複数リージョンのレプリカ間で双方向に非同期レプリケーションし、各リージョンで読み書きできる。リージョン障害時はアプリの向き先を切り替えるだけで継続可能。DAX はキャッシュ、GSI は別キーでの検索用。', 'generated'),
('D2', 'gen-batch-002', 43, ARRAY['compute']::text[], 2, 'ステートフルな Web アプリをスケールアウトしたところ、ロードバランサ配下でユーザーのログインセッションが頻繁に切れる。適切な対策はどれか。', '{"ア":"ALB のアイドルタイムアウトを最大値にする","イ":"Auto Scaling を無効化して 1 台に戻す","ウ":"各インスタンスのローカルディスクにセッションを保存する","エ":"セッション情報を ElastiCache(Redis)や DynamoDB など外部ストアに保存し、インスタンスをステートレスにする"}'::jsonb, 'エ', 'セッションをインスタンスローカルに持つと、別インスタンスへ振られた時に失われる。共有の外部ストア(Redis / DynamoDB)へ退避してインスタンスをステートレス化すれば、どの台に振られても継続できる。スティッキーセッションは応急策でしかない。', 'generated'),
('D2', 'gen-batch-002', 44, ARRAY['resilience']::text[], 2, 'オンプレミスと AWS の複数サービスのバックアップ(EBS、EFS、RDS、DynamoDB など)を一元的にポリシー管理し、保持期間やリージョン間コピーを統制したい。適切なサービスはどれか。', '{"ア":"Amazon S3 ライフサイクルポリシー","イ":"AWS DataSync","ウ":"AWS Backup","エ":"EBS スナップショットの手動作成スクリプト"}'::jsonb, 'ウ', 'AWS Backup はバックアッププラン(頻度・保持・コピー先)を作り、対象リソースをタグ等で選択して横断的に保護できるマネージドサービス。監査レポートやリージョン/アカウント間コピーにも対応。DataSync はデータ転送用。', 'generated'),
('D2', 'gen-batch-002', 45, ARRAY['integration']::text[], 3, '注文処理を「在庫引当 → 決済 → 配送手配」の順に、各ステップの成否やリトライ、補償処理を可視化しながらオーケストレーションしたい。適切なサービスはどれか。', '{"ア":"1 つの大きな Lambda 関数に全ステップを実装する","イ":"AWS Step Functions ステートマシン","ウ":"SQS キューを 3 本つなげてポーリングし続ける","エ":"EventBridge ルールだけでステップ間を連結する"}'::jsonb, 'イ', 'Step Functions は各ステップを状態として定義し、順序制御・条件分岐・リトライ/キャッチ・並列実行・タイムアウトを宣言的に管理でき、実行履歴を可視化できる。長時間・多段のワークフローに向く。巨大 Lambda はタイムアウトや可視性の問題がある。', 'generated'),
('D2', 'gen-batch-002', 46, ARRAY['compute']::text[], 3, 'Auto Scaling グループで、日中の予測可能な負荷増に事前に備えつつ、突発的なスパイクにも自動対応したい。適切な設定の組み合わせはどれか。', '{"ア":"スケジュールドスケーリングで日中の最小台数を引き上げ、ターゲット追跡スケーリングも併用する","イ":"手動で毎朝インスタンス数を変更する","ウ":"簡易スケーリングポリシーのみを 1 つ設定する","エ":"スケーリングを使わず最大台数で固定する"}'::jsonb, 'ア', '予測可能な波はスケジュールドスケーリング(時刻指定で min/desired を変更)で先回りし、読めないスパイクはターゲット追跡(例: 平均 CPU 50%)で追従させる。両者は併用でき、コストと応答性のバランスが取れる。固定最大台数は無駄が大きい。', 'generated'),
('D2', 'gen-batch-002', 47, ARRAY['network']::text[], 2, 'ALB のターゲットグループのヘルスチェックが失敗しているとき、ALB が取る動作として正しいものはどれか。', '{"ア":"異常なターゲットを自動的に終了して作り直す","イ":"全ターゲットへのトラフィックを停止する","ウ":"異常と判定したターゲットへの新規リクエスト送信を停止し、正常なターゲットのみへ振り分ける","エ":"異常なターゲットの OS を再起動する"}'::jsonb, 'ウ', 'ALB はヘルスチェック不合格のターゲットをローテーションから外し、正常なターゲットへのみルーティングする。インスタンスの終了・再作成は Auto Scaling(ELB ヘルスチェック連携時)の役割で、ALB 自身はインスタンスを操作しない。', 'generated'),
('D2', 'gen-batch-002', 48, ARRAY['database']::text[], 2, 'Aurora の可用性に関する説明として正しいものはどれか。', '{"ア":"データは単一 AZ の 1 ボリュームに保存される","イ":"フェイルオーバーには手動でのスナップショットリストアが必要","ウ":"リードレプリカは作成できない","エ":"データは 3 つの AZ に 6 個のコピーで保存され、レプリカを昇格させて自動フェイルオーバーできる"}'::jsonb, 'エ', 'Aurora のストレージは 3 AZ × 2 = 6 多重で自己修復する。Aurora レプリカ(最大 15)を配置しておくと、ライター障害時に数十秒で自動昇格・フェイルオーバーする。可用性と耐久性が RDS 標準より高い。', 'generated'),
('D2', 'gen-batch-002', 49, ARRAY['storage']::text[], 3, '複数の EC2 インスタンス(複数 AZ)から同時にマウントして読み書きできる共有ファイルシステムが必要で、AZ 障害にも耐えたい。適切なサービスはどれか。', '{"ア":"Amazon EBS io2 ボリュームを 1 つ作成して共有する","イ":"Amazon EFS(リージョン、標準ストレージクラス)","ウ":"インスタンスストア","エ":"S3 バケットを OS にファイルシステムとしてマウントする"}'::jsonb, 'イ', 'EFS は NFS 準拠のマネージド共有ファイルシステムで、複数 AZ のマウントターゲットを通じて多数のインスタンスから同時アクセスでき、データは複数 AZ に冗長化される。EBS は原則単一インスタンス・単一 AZ(Multi-Attach は io1/io2 かつ同一 AZ・用途限定)。', 'generated'),
('D2', 'gen-batch-002', 50, ARRAY['resilience']::text[], 2, '疎結合アーキテクチャがシステムの可用性に寄与する理由として最も適切なものはどれか。', '{"ア":"コンポーネント間をキューやロードバランサで分離することで、1 つの障害が全体へ連鎖しにくくなる","イ":"コンポーネント数が減るため障害点が少なくなる","ウ":"同期通信により障害を即座に検知できる","エ":"すべての処理を単一インスタンスに集約できる"}'::jsonb, 'ア', '疎結合では、あるコンポーネントが遅延・停止してもキューにメッセージが滞留し、他は動作を継続できる(障害の分離)。個々を独立にスケール/デプロイ/リトライでき、回復力が高い。密結合の同期呼び出しは失敗が伝播する。', 'generated'),
('D2', 'gen-batch-002', 51, ARRAY['compute']::text[], 3, 'バッチ処理をスポットインスタンスで安価に実行したいが、中断時にジョブが失われるのを避けたい。適切な対策はどれか。', '{"ア":"スポットインスタンスの入札価格をオンデマンドの 10 倍に設定する","イ":"中断通知(2 分前)をハンドリングしてチェックポイントを保存し、処理を SQS ベースで再開可能にする","ウ":"スポットを使わずすべてオンデマンドにする以外に方法はない","エ":"中断されないリージョンを選ぶ"}'::jsonb, 'イ', 'スポット中断は EC2 インスタンス中断通知(メタデータ/EventBridge)で 2 分前に分かる。これを受けて進捗をチェックポイント化し、未処理分を SQS に残す設計にすれば、別インスタンスが再開できる。フォールトトレラントなバッチにはスポットが有効。', 'generated'),
('D2', 'gen-batch-002', 52, ARRAY['network']::text[], 3, 'オンプレミスと AWS を接続する Direct Connect 単独構成の弱点を補い、接続の可用性を高める一般的な方法はどれか。', '{"ア":"Direct Connect の帯域を 2 倍にする","イ":"オンプレ側ルーターの設定を毎日バックアップする","ウ":"Site-to-Site VPN をバックアップ経路として併設し、Direct Connect 障害時にフェイルオーバーさせる","エ":"VPC のサブネットを追加する"}'::jsonb, 'ウ', 'Direct Connect は専用線ゆえ物理障害時に代替がないと切れる。コスト重視ならバックアップ VPN を張り、BGP で自動フェイルオーバーさせる。可用性最重視なら別ロケーションの 2 本目の Direct Connect を用いる。帯域増設は冗長性にはならない。', 'generated'),
('D2', 'gen-batch-002', 53, ARRAY['database']::text[], 3, 'RDS のリードレプリカを DR 目的で別リージョンに作成している。プライマリリージョンが全損した場合の復旧手順として正しいものはどれか。', '{"ア":"スナップショットからプライマリリージョンに新インスタンスを作るまで待つ","イ":"リードレプリカは自動的にプライマリへ昇格するので操作は不要","ウ":"マルチ AZ に変更すれば別リージョンで書き込める","エ":"クロスリージョンリードレプリカをスタンドアロンの DB インスタンスに昇格させ、アプリの接続先を変更する"}'::jsonb, 'エ', 'クロスリージョンリードレプリカは手動で「昇格」させると独立した読み書き可能インスタンスになる。アプリの接続文字列を新エンドポイントへ向けて復旧する。自動昇格はしない。マルチ AZ は同一リージョン内の HA。', 'generated'),
('D2', 'gen-batch-002', 54, ARRAY['integration']::text[], 2, 'SQS 標準キューの特性として正しいものはどれか。', '{"ア":"ほぼ無制限のスループットを持つが、順序保証はなく、まれにメッセージが重複配信される(at-least-once)","イ":"厳密な順序保証と正確に 1 回の配信を常に保証する","ウ":"1 秒あたり最大 10 メッセージまでしか送れない","エ":"メッセージは最大 1 時間しか保持できない"}'::jsonb, 'ア', '標準キューは高スループット・at-least-once 配信・ベストエフォート順序。厳密な順序と重複排除が必要なら FIFO キューを使う(スループット上限あり)。保持期間は既定 4 日、最大 14 日。コンシューマは冪等に設計する。', 'generated'),
('D2', 'gen-batch-002', 55, ARRAY['resilience']::text[], 2, 'ステートレスな Web 層の前段に ALB、背後に複数 AZ の Auto Scaling を置いた。さらに単一障害点を減らすために確認すべき箇所はどれか。', '{"ア":"ALB を 2 つに増やす","イ":"EC2 の CPU クレジットが枯渇していないか","ウ":"データベースがシングル AZ になっていないか(マルチ AZ 化を検討する)","エ":"S3 バケットのリージョンを変更する"}'::jsonb, 'ウ', 'Web 層は冗長化済みでも、バックエンド DB が単一 AZ なら依然として単一障害点。RDS マルチ AZ や Aurora へ移行して自動フェイルオーバーを確保する。ALB はそれ自体がマネージドで複数 AZ 冗長なので増設不要。', 'generated'),
('D2', 'gen-batch-002', 56, ARRAY['compute']::text[], 2, 'Auto Scaling グループの「希望容量(Desired Capacity)」「最小」「最大」の関係で正しい説明はどれか。', '{"ア":"スケーリングポリシーは希望容量を最小と最大の範囲内で増減させ、その台数を維持しようとする","イ":"最大容量を超えても負荷が高ければ自動で最大値が引き上げられる","ウ":"最小容量は 0 に設定できない","エ":"希望容量は常に最大容量と等しくなる"}'::jsonb, 'ア', 'ASG は希望容量に台数を合わせ、ヘルスチェック不合格分を補充する。スケーリングポリシーが希望容量を [最小, 最大] の範囲で調整する。最大値は自動では超えない。最小 0 も設定可能(オンデマンドなワークロード)。', 'generated'),
('D2', 'gen-batch-002', 57, ARRAY['network']::text[], 2, '1 つのリージョン内で ALB を使う場合、可用性のために少なくとも満たすべき条件はどれか。', '{"ア":"ALB を 1 つの AZ に固定し、その AZ にターゲットを集約する","イ":"ALB の代わりに単一の EC2 で HAProxy を動かす","ウ":"ALB をパブリックサブネットではなくプライベートサブネットのみに置く","エ":"ALB を 2 つ以上の AZ のサブネットに関連付け、各 AZ にターゲットを配置する"}'::jsonb, 'エ', 'ALB は関連付けた各 AZ にノードを作り、その AZ のターゲットへ分散する。2 つ以上の AZ を有効化し各 AZ にターゲットを置くことで、1 AZ 障害でも残りの AZ で処理を継続できる。単一 EC2 のプロキシは単一障害点。', 'generated'),
('D2', 'gen-batch-002', 58, ARRAY['storage']::text[], 2, 'S3 標準ストレージクラスの耐久性・可用性に関する説明として正しいものはどれか。', '{"ア":"オブジェクトは単一 AZ にのみ保存される","イ":"オブジェクトは複数 AZ に冗長化され、99.999999999%(イレブンナイン)の耐久性を持つよう設計されている","ウ":"耐久性は 99.9% で、定期的な手動バックアップが前提となる","エ":"可用性を高めるにはユーザーがレプリケーションを必須で構成する必要がある"}'::jsonb, 'イ', 'S3 標準は複数 AZ にまたがってデータを保存し、11 ナインの耐久性・99.99% の可用性 SLA を目標に設計されている。単一 AZ 保存は S3 One Zone-IA の特性。追加のバックアップは要件次第で任意。', 'generated'),
('D2', 'gen-batch-002', 59, ARRAY['resilience']::text[], 3, '重要な本番ワークロードの回復力を、実際に障害を注入して継続的に検証したい。AWS が提供するサービスはどれか。', '{"ア":"AWS Trusted Advisor","イ":"AWS Fault Injection Service(FIS)","ウ":"Amazon CloudWatch Synthetics","エ":"AWS Config"}'::jsonb, 'イ', 'AWS FIS はマネージドなカオスエンジニアリングサービスで、EC2 停止、API スロットリング、AZ 影響のシミュレーションなどのフォールトを制御された条件下で注入し、システムの回復挙動やアラームを検証できる。Synthetics は外形監視。', 'generated'),
('D2', 'gen-batch-002', 60, ARRAY['resilience']::text[], 3, '静的ウェブサイトを可能な限り高い可用性で、かつサーバー管理なしでホスティングしたい。最も可用性が高く運用が軽い構成はどれか。', '{"ア":"単一 AZ の EC2 1 台に Nginx を構築する","イ":"オンプレのサーバーに DNS を向ける","ウ":"複数リージョンの EC2 を手動で同期する","エ":"S3(静的ホスティング)+ CloudFront + Route 53。オリジンもCDNもマネージドで多AZ冗長"}'::jsonb, 'エ', '静的サイトは S3 + CloudFront + Route 53 が定番。S3 は複数 AZ 冗長で 11 ナインの耐久性、CloudFront はグローバルエッジ、Route 53 は高可用 DNS。いずれもフルマネージドで、パッチやスケーリングの運用がなく、単一障害点も少ない。', 'generated');
